from ledger import write

def store(acct, wire):
    # Validate check digit
    if '#' not in wire:
        raise ValueError("Invalid wire format")
    sign_digits, check = wire.rsplit('#', 1)
    if sign_digits[0] not in ('+', '-'):
        raise ValueError("Invalid sign")
    digits = sign_digits[1:]
    if not digits.isdigit():
        raise ValueError("Invalid digits")

    # Validate check digit: (sum of decimal digits in digits) mod 10
    digit_sum = sum(int(d) for d in digits)
    expected_check = str(digit_sum % 10)
    if check != expected_check:
        raise ValueError(f"Check digit mismatch: expected {expected_check}, got {check}")

    return write(acct, 'wire', wire)

